// Generate History, Geometry, ICT notes (64 files total)
const fs = require('fs');
const path = require('path');

const notesDir = path.join(__dirname, 'notes');

function template(title, code, igcse, asl, a2, summary) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${title} — LearnAI</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<link rel="stylesheet" href="../css/styles.css?v=3">
<style>
.notes-page { padding: 120px 0 60px; background: var(--light); min-height: 100vh; }
.notes-container { max-width: 900px; margin: 0 auto; background: var(--white); padding: 48px; border-radius: var(--radius-xl); box-shadow: var(--shadow); }
.notes-header { margin-bottom: 40px; padding-bottom: 24px; border-bottom: 2px solid var(--gray-light); }
.notes-header h1 { font-size: 2rem; margin-bottom: 12px; }
.level-badges { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 16px; }
.level-badge { padding: 4px 12px; border-radius: 50px; font-size: 0.75rem; font-weight: 600; text-transform: uppercase; }
.badge-igcse { background: #dbeafe; color: #1e40af; }
.badge-as { background: #dcfce7; color: #166534; }
.badge-a2 { background: #fef3c7; color: #92400e; }
.notes-section { margin-bottom: 40px; }
.notes-section h2 { font-size: 1.4rem; color: var(--primary-dark); margin-bottom: 16px; padding-bottom: 8px; border-bottom: 2px solid var(--primary-light); }
.notes-section h3 { font-size: 1.1rem; color: var(--dark); margin: 24px 0 12px; }
.notes-section p { margin-bottom: 12px; line-height: 1.8; color: var(--dark-light); }
.notes-section ul { margin: 12px 0; padding-left: 24px; }
.notes-section ul li { margin-bottom: 8px; color: var(--dark-light); line-height: 1.7; }
.formula-box { background: var(--light); padding: 16px 20px; border-radius: var(--radius); border-left: 4px solid var(--primary); font-family: 'Courier New', monospace; margin: 16px 0; font-size: 0.95rem; }
.summary-box { background: linear-gradient(135deg, #fef9c3 0%, #fde047 100%); padding: 24px; border-radius: var(--radius-lg); margin-top: 32px; }
.summary-box h3 { color: #92400e; margin-bottom: 12px; }
.back-btn { display: inline-flex; align-items: center; gap: 8px; margin-bottom: 24px; color: var(--primary); font-weight: 600; }
</style>
</head>
<body>
<nav class="navbar"><div class="container nav-container"><a href="../index.html" class="logo"><span class="logo-icon">🎓</span><span class="logo-text">LearnAI</span></a></div></nav>
<section class="notes-page"><div class="container">
<a href="../subject.html?id=${code.split('-')[0]}" class="back-btn">← Back to ${code.split('-')[0].charAt(0).toUpperCase() + code.split('-')[0].slice(1)}</a>
<div class="notes-container">
<div class="notes-header">
<div class="level-badges">
<span class="level-badge badge-igcse">IGCSE</span>
<span class="level-badge badge-as">AS</span>
<span class="level-badge badge-a2">A2</span>
</div>
<h1>${title}</h1>
<p style="color:var(--gray)">${code}</p>
</div>
<div class="notes-section"><h2>📘 IGCSE Content</h2>${igcse}</div>
<div class="notes-section"><h2>📗 AS Level Content</h2>${asl}</div>
<div class="notes-section"><h2>📙 A2 Level Content</h2>${a2}</div>
<div class="summary-box"><h3>📝 Last-Minute Summary</h3>${summary}</div>
</div>
</div></section>
<script src="../js/auth.js?v=3"></script><script src="../js/app.js?v=3"></script>
</body></html>`;
}

function summaryTemplate(title, code, summary) {
  return template(title, code, `<p><em>See full notes for detailed IGCSE content.</em></p>`, `<p><em>See full notes for detailed AS Level content.</em></p>`, `<p><em>See full notes for detailed A2 Level content.</em></p>`, summary);
}

// === HISTORY TOPICS ===
const historyTopics = [
  { id:'h1', title:'The Origins of World War I, 1871–1914',
    igcse:`<h3>The Alliance System</h3><ul><li><strong>Triple Alliance (1882):</strong> Germany, Austria-Hungary, Italy — Bismarck's diplomatic creation to isolate France</li><li><strong>Triple Entente (1907):</strong> Britain, France, Russia — formed in response to German expansion</li><li><strong>Significance:</strong> Turned regional disputes into continental conflicts; guaranteed escalation</li></ul><h3>Militarism</h3><ul><li><strong>Arms race:</strong> Germany's naval expansion challenged British supremacy; Dreadnought crisis 1909</li><li><strong>Schlieffen Plan:</strong> German strategy for two-front war — attack France through Belgium first</li><li><strong>Conscription:</strong> All major powers had large standing armies by 1914</li></ul><h3>Imperialism</h3><ul><li><strong>Moroccan Crises (1905, 1911):</strong> Germany challenged French influence; heightened tensions</li><li><strong>Balkan Wars (1912–13):</strong> Weakened Ottoman Empire; Serbia emerged stronger</li></ul><h3>The July Crisis 1914</h3><ul><li><strong>28 June:</strong> Archduke Franz Ferdinand assassinated in Sarajevo by Gavrilo Princip (Black Hand)</li><li><strong>23 July:</strong> Austria-Hungary issued impossible ultimatum to Serbia</li><li><strong>28 July:</strong> Austria declared war on Serbia</li><li><strong>1 August:</strong> Germany declared war on Russia</li><li><strong>3 August:</strong> Germany declared war on France; invaded Belgium</li><li><strong>4 August:</strong> Britain declared war on Germany (guarantee to Belgium, 1839)</li></ul>`,
    as:`<h3>Historiographical Debates</h3><ul><li><strong>Fischer Thesis (1961):</strong> Germany deliberately planned war; "War Council" December 1912 as evidence of intent</li><li><strong>Counter-arguments:</strong> Clark (Sleepwalkers) — all powers share blame; crisis mismanagement not deliberate planning</li><li><strong>Structural vs intentionalist:</strong> Were long-term forces or short-term decisions more important?</li></ul><h3>Source Evaluation</h3><ul><li>Grey's speech to Parliament (3 Aug 1914): Justification for British entry</li><li>Bethmann-Hollweg's "blank cheque": Evidence of German encouragement to Austria</li></ul>`,
    a2:`<h3>Thematic Synthesis</h3><ul><li><strong>German responsibility:</strong> Weltpolitik, naval expansion, support for Austria — but other powers made choices too</li><li><strong>Role of nationalism:</strong> Pan-Slavism vs Pan-Germanism; Serbian nationalism as trigger</li><li><strong>Systemic failure:</strong> Alliance system + mobilisation timetables made war difficult to stop once started</li></ul><h3>Essay Frameworks</h3><ul><li><strong>"Germany was solely responsible":</strong> Evaluate Fischer evidence vs structural factors</li><li><strong>"Short-term causes were more important":</strong> July Crisis analysis vs long-term militarism</li></ul>`,
    summary:`<ul><li><strong>Long-term causes:</strong> Alliance system, militarism, imperialism, nationalism</li><li><strong>Short-term trigger:</strong> Assassination of Franz Ferdinand, 28 June 1914</li><li><strong>July Crisis:</strong> Ultimatum → Austria-Serbia war → German mobilisation → world war</li><li><strong>British entry:</strong> German invasion of Belgium (Treaty of London 1839)</li><li><strong>Fischer thesis:</strong> Germany planned war deliberately</li><li><strong>Clark thesis:</strong> All powers were "sleepwalkers" — shared blame</li><li><strong>Exam tip:</strong> Always balance long-term and short-term factors; use specific dates</li></ul>` },

  { id:'h2', title:'The Holocaust',
    igcse:`<h3>Definition</h3><p>The systematic, state-sponsored persecution and murder of approximately 6 million Jews by Nazi Germany and collaborators between 1941 and 1945.</p><h3>Stages of Persecution</h3><ul><li><strong>1933–35:</strong> Boycotts, Nuremberg Laws (stripped citizenship, banned intermarriage)</li><li><strong>1938:</strong> Kristallnacht — state-organised pogrom; 30,000 sent to concentration camps</li><li><strong>1939–41:</strong> Ghettoisation — Warsaw, Lodz, Krakow; forced labour</li><li><strong>1941–45:</strong> Final Solution — Einsatzgruppen (mass shootings), extermination camps (Auschwitz, Treblinka, Sobibor)</li></ul><h3>Key Events</h3><ul><li><strong>Wannsee Conference (20 Jan 1942):</strong> Coordinated implementation of Final Solution</li><li><strong>Auschwitz-Birkenau:</strong> Largest death camp; 1.1 million killed, mostly Jews</li></ul>`,
    as:`<h3>Ideological Roots</h3><ul><li><strong>Anti-Semitism:</strong> Historical prejudice + pseudo-scientific racial theories</li><li><strong>Volksgemeinschaft:</strong> Racial community excluding Jews</li><li><strong>Lebensraum:</strong> Need for living space in East — Jews as obstacle</li></ul><h3>Role of Collaboration</h3><ul><li>Vichy France, Hungary, Romania — local administrations assisted deportations</li><li>Some resistance: Denmark saved most Jews; Bulgaria refused deportations</li></ul>`,
    a2:`<h3>Historiography</h3><ul><li><strong>Intentionalists:</strong> Hitler planned genocide from early (Mein Kampf 1925)</li><li><strong>Functionalists:</strong> Holocaust emerged from wartime radicalisation; cumulative radicalisation</li><li><strong>Browning (Ordinary Men):</strong> Ordinary Germans participated — not just fanatics</li></ul><h3>Comparison & Significance</h3><ul><li>Unique or part of broader genocide? Comparison with other 20th century atrocities</li><li>Memory and memorialisation: Yad Vashem, Holocaust Memorial Day</li></ul>`,
    summary:`<ul><li><strong>Definition:</strong> Systematic murder of 6 million Jews (1941–45)</li><li><strong>Stages:</strong> Persecution (1933) → Ghettos (1939) → Final Solution (1941)</li><li><strong>Key event:</strong> Wannsee Conference (Jan 1942)</li><li><strong>Intentionalist:</strong> Hitler planned it from start</li><li><strong>Functionalist:</strong> Emerged from wartime conditions</li><li><strong>Exam tip:</strong> Use specific camp names and dates; balance perpetrator and victim perspectives</li></ul>` },

  { id:'h3', title:'The Cold War in Europe, 1941–1995',
    igcse:`<h3>Origins (1941–47)</h3><ul><li><strong>Grand Alliance tensions:</strong> Different ideologies, delayed Second Front</li><li><strong>Yalta (Feb 1945):</strong> Agreed on post-war Germany; disagreed on Poland</li><li><strong>Potsdam (July 1945):</strong> Truman (atomic bomb knowledge), Stalin — increasing suspicion</li><li><strong>Iron Curtain speech (March 1946):</strong> Churchill — symbolic division of Europe</li></ul><h3>Containment & Expansion</h3><ul><li><strong>Truman Doctrine (1947):</strong> US commitment to stop communism globally</li><li><strong>Marshall Plan (1948):</strong> $13bn economic aid to rebuild Western Europe</li><li><strong>Berlin Blockade (1948–49):</strong> Soviet test; defeated by Western airlift</li><li><strong>NATO (1949):</strong> Military alliance of Western powers</li></ul><h3>Key Crises</h3><ul><li><strong>Hungarian Uprising (1956):</strong> Crushed by Soviet tanks; West did not intervene</li><li><strong>Berlin Wall (1961):</strong> Symbol of division; stopped refugee flow</li><li><strong>Prague Spring (1968):</strong> Dubcek's reforms crushed by Warsaw Pact invasion</li></ul>`,
    as:`<h3>Ideological Conflict</h3><ul><li><strong>Capitalism vs Communism:</strong> Free markets vs state planning; democracy vs one-party rule</li><li><strong>Security dilemma:</strong> Both sides saw defensive measures as threats</li></ul><h3>Détente (1969–79)</h3><ul><li><strong>SALT I (1972):</strong> Limited nuclear arms</li><li><strong>Helsinki Accords (1975):</strong> Recognised post-war borders; human rights provisions</li><li><strong>Reasons:</strong> Nuclear parity, economic costs, Sino-Soviet split</li></ul>`,
    a2:`<h3>End of Cold War (1985–91)</h3><ul><li><strong>Gorbachev's reforms:</strong> Glasnost (openness) + Perestroika (restructuring)</li><li><strong>Fall of Berlin Wall (9 Nov 1989):</strong> Symbolic end of division</li><li><strong>German reunification (1990):</strong> NATO membership issue resolved</li><li><strong>Soviet collapse (Dec 1991):</strong> Gorbachev resigned; USSR dissolved</li></ul><h3>Historiography</h3><ul><li><strong>Traditionalists:</strong> Soviet expansion caused Cold War</li><li><strong>Revisionists:</strong> US economic imperialism provoked Soviet response</li><li><strong>Post-revisionists:</strong> Mutual misunderstanding and security dilemma</li></ul>`,
    summary:`<ul><li><strong>1945:</strong> Grand Alliance fractures over Poland, Germany</li><li><strong>1947–49:</strong> Truman Doctrine, Marshall Plan, Berlin Blockade, NATO</li><li><strong>1950s–60s:</strong> Hungarian Uprising (1956), Berlin Wall (1961), Prague Spring (1968)</li><li><strong>1969–79:</strong> Détente — SALT I, Helsinki</li><li><strong>1985–91:</strong> Gorbachev, fall of Berlin Wall, Soviet collapse</li><li><strong>Historiography:</strong> Traditionalist (Soviet blame) vs Revisionist (US blame) vs Post-revisionist (both)</li></ul>` },

  { id:'h4', title:'The Cold War in Asia, 1945–1991',
    igcse:`<h3>Chinese Civil War & Communist Victory</h3><ul><li><strong>1945–49:</strong> Civil war resumes after Japanese defeat</li><li><strong>CCP victory (1949):</strong> Mao Zedong proclaims People's Republic; Chiang Kai-shek retreats to Taiwan</li><li><strong>Reasons for CCP victory:</strong> Peasant support, effective guerrilla warfare, KMT corruption</li></ul><h3>Korean War (1950–53)</h3><ul><li><strong>June 1950:</strong> North Korea (Kim Il-sung) invades South</li><li><strong>UN intervention:</strong> Led by US General MacArthur</li><li><strong>Chinese intervention (Oct 1950):</strong> 300,000 "volunteers" push UN back to 38th parallel</li><li><strong>Armistice (1953):</strong> Korea remains divided at 38th parallel</li></ul><h3>Vietnam War</h3><ul><li><strong>1954:</strong> Geneva Conference divides Vietnam at 17th parallel</li><li><strong>US escalation:</strong> Gulf of Tonkin incident (1964) → full ground war</li><li><strong>Tet Offensive (1968):</strong> Military defeat but psychological victory for Viet Cong</li><li><strong>US withdrawal (1973):</strong> Paris Peace Accords</li><li><strong>Fall of Saigon (1975):</strong> Communist victory; reunification</li></ul>`,
    as:`<h3>Containment in Asia</h3><ul><li><strong>Domino Theory:</strong> If one country falls to communism, others will follow</li><li><strong>SEATO (1954):</strong> Southeast Asia Treaty Organisation</li><li><strong>Cost of containment:</strong> 58,000 US deaths in Vietnam; $150bn spent</li></ul><h3>Sino-Soviet Split</h3><ul><li><strong>Ideological differences:</strong> Mao's revolutionary fervour vs Khrushchev's peaceful coexistence</li><li><strong>1960:</strong> Soviet advisors withdrawn from China</li><li><strong>1969:</strong> Border clashes — potential for Sino-US rapprochement</li></ul>`,
    a2:`<h3>US-China Rapprochement</h3><ul><li><strong>1971:</strong> Kissinger secret visit; Ping-Pong diplomacy</li><li><strong>1972:</strong> Nixon visits China; Shanghai Communiqué</li><li><strong>Strategic significance:</strong> Triangular diplomacy — US plays China against USSR</li></ul><h3>Why Communism Succeeded in Asia</h3><ul><li><strong>Anti-colonialism:</strong> Communism linked to national liberation</li><li><strong>Peasant support:</strong> Land reform promises</li><li><strong>US failures:</strong> Supported unpopular regimes (Diem, Chiang)</li></ul>`,
    summary:`<ul><li><strong>1949:</strong> Communist victory in China; Mao proclaims PRC</li><li><strong>1950–53:</strong> Korean War — divided at 38th parallel</li><li><strong>1954:</strong> Vietnam divided at 17th parallel</li><li><strong>1964–73:</strong> US Vietnam War escalation and withdrawal</li><li><strong>1975:</strong> Fall of Saigon — communist victory</li><li><strong>1972:</strong> Nixon visits China — Sino-US rapprochement</li><li><strong>Domino Theory:</strong> Justification for US intervention</li></ul>` },

  { id:'h5', title:'Civil Rights in the USA, 1863–1968',
    igcse:`<h3>Reconstruction (1865–77)</h3><ul><li><strong>13th Amendment (1865):</strong> Abolished slavery</li><li><strong>14th Amendment (1868):</strong> Citizenship and equal protection</li><li><strong>15th Amendment (1870):</strong> Voting rights regardless of race</li><li><strong>Failure:</strong> Jim Crow laws, sharecropping, KKK violence</li></ul><h3>Jim Crow Era (1877–1954)</h3><ul><li><strong>Plessy v Ferguson (1896):</strong> "Separate but equal" justified segregation</li><li><strong>Disenfranchisement:</strong> Poll taxes, literacy tests, grandfather clauses</li><li><strong>Economic discrimination:</strong> Limited jobs, lower wages, segregated facilities</li></ul><h3>Montgomery Bus Boycott (1955–56)</h3><ul><li><strong>Rosa Parks:</strong> Refused to give up seat (1 Dec 1955)</li><li><strong>Martin Luther King Jr:</strong> Emerged as leader; 381-day boycott</li><li><strong>Result:</strong> Supreme Court banned bus segregation (Browder v Gayle)</li></ul><h3>Key Legislation</h3><ul><li><strong>Civil Rights Act (1964):</strong> Banned discrimination in public places and employment</li><li><strong>Voting Rights Act (1965):</strong> Eliminated literacy tests; federal oversight</li></ul>`,
    as:`<h3>Campaign Strategies</h3><ul><li><strong>NAACP:</strong> Legal strategy — challenged segregation in courts (Brown v Board 1954)</li><li><strong>SCLC:</strong> Non-violent direct action; moral persuasion</li><li><strong>SNCC:</strong> Student activism; Freedom Rides (1961), Freedom Summer (1964)</li><li><strong>Nation of Islam:</strong> Black separatism; Malcolm X until 1965</li></ul><h3>Opposition & Violence</h3><ul><li><strong>White Citizens' Councils:</strong> Economic boycott of activists</li><li><strong>KKK:</strong> Bombings, murders, intimidation</li><li><strong>Police brutality:</strong> Birmingham (1963) — attacked with dogs and fire hoses</li></ul>`,
    a2:`<h3>Evaluation of Success</h3><ul><li><strong>Political:</strong> Voting rights secured; Black elected officials increased</li><li><strong>Economic:</strong> Limited progress — wealth gap persisted</li><li><strong>Social:</strong> De jure segregation ended; de facto segregation remained</li><li><strong>Black Power:</strong> Stokely Carmichael, Black Panthers — shift from integration to empowerment</li></ul><h3>Comparative Analysis</h3><ul><li>Comparison with other civil rights movements globally</li><li>Role of federal government vs grassroots activism</li></ul>`,
    summary:`<ul><li><strong>1865–77:</strong> Reconstruction Amendments; failed to secure equality</li><li><strong>1896:</strong> Plessy v Ferguson — "separate but equal"</li><li><strong>1954:</strong> Brown v Board — desegregation</li><li><strong>1955–56:</strong> Montgomery Bus Boycott — MLK emerges</li><li><strong>1963:</strong> March on Washington — "I Have a Dream"</li><li><strong>1964:</strong> Civil Rights Act</li><li><strong>1965:</strong> Voting Rights Act; Malcolm X assassinated</li><li><strong>1968:</strong> MLK assassinated</li></ul>` },

  { id:'h6', title:'International History, 1945–1991',
    igcse:`<h3>Post-War Settlement</h3><ul><li><strong>UN established (1945):</strong> Security Council with veto power for 5 permanent members</li><li><strong>Decolonisation:</strong> India (1947), Ghana (1957), Algeria (1962) — end of European empires</li></ul><h3>Non-Aligned Movement</h3><ul><li><strong>Bandung Conference (1955):</strong> 29 Asian-African nations; Nehru, Nasser, Tito, Sukarno</li><li><strong>Principles:</strong> Neutral in Cold War; anti-colonialism; peaceful coexistence</li></ul><h3>Middle East Conflicts</h3><ul><li><strong>Suez Crisis (1956):</strong> Nasser nationalised canal; UK-France-Israel invasion; US-USSR forced withdrawal</li><li><strong>Six-Day War (1967):</strong> Israel defeated Egypt, Syria, Jordan; occupied West Bank, Gaza, Golan Heights</li><li><strong>Yom Kippur War (1973):</strong> Arab oil embargo; US support for Israel</li></ul>`,
    as:`<h3>Arms Race & Nuclear Proliferation</h3><ul><li><strong>1949:</strong> USSR tests atomic bomb — end of US monopoly</li><li><strong>1952:</strong> US tests hydrogen bomb</li><li><strong>1962:</strong> Cuban Missile Crisis — closest to nuclear war</li><li><strong>NPT (1968):</strong> Nuclear Non-Proliferation Treaty</li></ul><h3>Proxy Wars</h3><ul><li><strong>Angola (1975–2002):</strong> Cold War proxy; Cuba backed MPLA, US/South Africa backed UNITA</li><li><strong>Afghanistan (1979–89):</strong> Soviet invasion; US armed mujahideen (including Bin Laden)</li></ul>`,
    a2:`<h3>End of Bipolar World</h3><ul><li><strong>Gorbachev's "New Thinking":</strong> Retreat from confrontation; withdraw from Afghanistan</li><li><strong>Revolutions of 1989:</strong> Eastern European states overthrow communist regimes</li><li><strong>German reunification:</strong> Kohl's "10-point plan"; 2+4 Treaty</li></ul><h3>Legacy</h3><ul><li>New world order? Unipolar moment vs emerging multipolarity</li><li>NATO expansion; EU integration</li></ul>`,
    summary:`<ul><li><strong>1945:</strong> UN established; decolonisation begins</li><li><strong>1955:</strong> Bandung — Non-Aligned Movement</li><li><strong>1956:</strong> Suez Crisis — end of British/French imperial power</li><li><strong>1962:</strong> Cuban Missile Crisis</li><li><strong>1967:</strong> Six-Day War</li><li><strong>1979–89:</strong> Soviet-Afghan War</li><li><strong>1989–91:</strong> End of Cold War; Soviet collapse</li></ul>` },

  { id:'h7', title:'The French Revolution, 1774–1794',
    igcse:`<h3>Causes</h3><ul><li><strong>Social:</strong> Three Estates system — clergy (1%), nobility (2%), commoners (97%)</li><li><strong>Economic:</strong> Debt from wars (American Revolution, Seven Years' War); bad harvests 1787–88</li><li><strong>Political:</strong> Absolute monarchy; Estates-General not called since 1614</li><li><strong>Intellectual:</strong> Enlightenment ideas — Rousseau, Voltaire, Montesquieu</li></ul><h3>Key Events</h3><ul><li><strong>5 May 1789:</strong> Estates-General convenes at Versailles</li><li><strong>20 June 1789:</strong> Tennis Court Oath — Third Estate forms National Assembly</li><li><strong>14 July 1789:</strong> Storming of the Bastille</li><li><strong>26 August 1789:</strong> Declaration of Rights of Man and Citizen</li><li><strong>1792:</strong> Monarchy abolished; Louis XVI executed (21 Jan 1793)</li><li><strong>1793–94:</strong> Reign of Terror — Robespierre, Committee of Public Safety, guillotine</li></ul>`,
    as:`<h3>Revolutionary Government</h3><ul><li><strong>Constitutional Monarchy (1789–92):</strong> Limited royal power; National Assembly</li><li><strong>Girondins vs Jacobins:</strong> Moderate republicans vs radical revolutionaries</li><li><strong> sans-culottes:</strong> Urban working class; demanded price controls and direct democracy</li></ul><h3>Reforms</h3><ul><li>Abolition of feudalism (4 Aug 1789)</li><li>Civil Constitution of the Clergy (1790) — state control of Church</li><li>Metric system introduced</li></ul>`,
    a2:`<h3>Terror & Thermidor</h3><ul><li><strong>Law of Suspects (1793):</strong> Anyone suspected of opposing the revolution could be arrested</li><li><strong>Robespierre's fall (July 1794):</strong> Thermidorian Reaction; executed 9 Thermidor</li><li><strong>Directory (1795–99):</strong> Five-man executive; corruption and instability</li></ul><h3>Historiography</h3><ul><li><strong>Marxist:</strong> Bourgeois revolution against feudalism</li><li><strong>Cobban:</strong> Not a bourgeois revolution — social groups not clearly defined</li><li><strong>Furet:</strong> Ideological revolution; importance of political culture</li></ul>`,
    summary:`<ul><li><strong>Causes:</strong> Social inequality, debt, Enlightenment ideas</li><li><strong>1789:</strong> Estates-General → Tennis Court Oath → Bastille (14 July)</li><li><strong>1789:</strong> Declaration of Rights of Man</li><li><strong>1792:</strong> Republic declared; Louis XVI executed</li><li><strong>1793–94:</strong> Reign of Terror; Robespierre</li><li><strong>1794:</strong> Thermidorian Reaction; Directory established</li></ul>` },

  { id:'h8', title:'Hitler\'s Germany, 1929–1947',
    igcse:`<h3>Rise to Power</h3><ul><li><strong>Wall Street Crash (1929):</strong> German economy collapses; unemployment reaches 6 million</li><li><strong>Nazi appeal:</strong> Promise of jobs, national pride, scapegoating Jews</li><li><strong>1930 election:</strong> Nazis become second largest party (107 seats)</li><li><strong>July 1932:</strong> Nazis largest party (230 seats)</li><li><strong>Jan 1933:</strong> Hitler appointed Chancellor</li></ul><h3>Consolidation of Power</h3><ul><li><strong>Reichstag Fire (Feb 1933):</strong> Blamed on communists; Emergency Decrees</li><li><strong>Enabling Act (March 1933):</strong> Hitler could rule by decree for 4 years</li><li><strong>Night of Long Knives (June 1934):</strong> SA leaders killed; army loyalty secured</li><li><strong>Hindenburg's death (Aug 1934):</strong> Hitler becomes Führer</li></ul><h3>Nazi State</h3><ul><li><strong>Gestapo:</strong> Secret police; surveillance and terror</li><li><strong>Propaganda:</strong> Goebbels; radio, films, rallies, Olympics (1936)</li><li><strong>Education:</strong> Indoctrination; Hitler Youth compulsory (1936)</li></ul>`,
    as:`<h3>Economic Policy</h3><ul><li><strong>Work Creation Programmes:</strong> Autobahns, rearmament</li><li><strong>Rearmament:</strong> Violated Versailles Treaty; reduced unemployment</li><li><strong>Four-Year Plan (1936):</strong> Autarky (self-sufficiency); Göring</li></ul><h3>Foreign Policy</h3><ul><li><strong>1933:</strong> Left League of Nations</li><li><strong>1935:</strong> Reintroduced conscription</li><li><strong>1936:</strong> Remilitarised Rhineland</li><li><strong>1938:</strong> Anschluss with Austria; Munich Agreement (Sudetenland)</li></ul>`,
    a2:`<h3>Resistance & Opposition</h3><ul><li><strong>White Rose:</strong> Student group (1942–43); executed</li><li><strong>July Bomb Plot (1944):</strong> Stauffenberg; failed assassination</li><li><strong>Edelweiss Pirates:</strong> Working-class youth; graffiti and sabotage</li></ul><h3>Totalitarianism Debate</h3><ul><li><strong>Intentionalist:</strong> Hitler planned everything (Mein Kampf as blueprint)</li><li><strong>Structuralist:</strong> Chaotic Nazi state; polycratic competition</li><li><strong>Wehler:</strong> "Cumulative radicalisation" — initiatives from below</li></ul>`,
    summary:`<ul><li><strong>1929:</strong> Wall Street Crash → Nazi support rises</li><li><strong>Jan 1933:</strong> Hitler appointed Chancellor</li><li><strong>Feb 1933:</strong> Reichstag Fire → Emergency powers</li><li><strong>March 1933:</strong> Enabling Act</li><li><strong>1934:</strong> Night of Long Knives; Hitler becomes Führer</li><li><strong>1935–38:</strong> Rearmament, Rhineland, Anschluss, Munich</li><li><strong>Totalitarian debate:</strong> Intentionalist vs Structuralist</li></ul>` },

  { id:'h9', title:'Stalin\'s Russia, 1924–1953',
    igcse:`<h3>Power Struggle (1924–29)</h3><ul><li><strong>Lenin dies (1924):</strong> Testament criticised Stalin; not published</li><li><strong>Trotsky:</strong> Brilliant orator; Red Army founder; "permanent revolution"</li><li><strong>Stalin:</strong> General Secretary; built power base in party apparatus</li><li><strong>Strategies:</strong> Allied with Zinoviev and Kamenev against Trotsky; then against them</li><li><strong>1929:</strong> Trotsky expelled; Stalin sole leader</li></ul><h3>Collectivisation</h3><ul><li><strong>1929:</strong> Forced merger of small farms into collective farms (kolkhoz)</li><li><strong>Kulaks:</strong> Wealthy peasants; deported or killed (5 million deaths)</li><li><strong>Consequences:</strong> Famine 1932–33 (Ukraine — Holodomor); 7+ million dead</li></ul><h3>Five-Year Plans</h3><ul><li><strong>1st Plan (1928–32):</strong> Heavy industry; Magnitogorsk, Dnieprostroi</li><li><strong>2nd Plan (1933–37):</strong> Stakhanovite movement; continued industrial growth</li><li><strong>Results:</strong> USSR became industrial power; consumer goods neglected</li></ul>`,
    as:`<h3>Great Terror (1936–38)</h3><ul><li><strong>Show trials:</strong> Old Bolsheviks confessed to fabricated crimes (Zinoviev, Kamenev, Bukharin)</li><li><strong>Purges:</strong> 700,000 executed; millions sent to Gulag</li><li><strong>Reasons:</strong> Eliminate rivals; create scapegoats; maintain fear</li></ul><h3>Propaganda & Cult of Personality</h3><ul><li><strong>Stalin portrayed as:</strong> Father of the nation, genius, Lenin's true heir</li><li><strong>Control of media:</strong> All newspapers, radio, film state-controlled</li><li><strong>Education:</strong> Marxist-Leninist curriculum; history rewritten</li></ul>`,
    a2:`<h3>World War II & Post-War</h3><ul><li><strong>Great Patriotic War (1941–45):</strong> 27 million Soviet deaths; Stalin's leadership questioned after early defeats</li><li><strong>Post-war:</strong> USSR emerges as superpower; Eastern Europe under Soviet control</li><li><strong>Cold War begins:</strong> Stalin's suspicion of West; Iron Curtain</li></ul><h3>Evaluation of Stalinism</h3><ul><li><strong>Achievements:</strong> Industrialisation, victory in WWII, superpower status</li><li><strong>Costs:</strong> Famine, terror, Gulag, environmental destruction, loss of freedoms</li><li><strong>Comparison:</strong> Stalin vs Hitler — totalitarian parallels and differences</li></ul>`,
    summary:`<ul><li><strong>1924–29:</strong> Power struggle; Stalin defeats Trotsky</li><li><strong>1929:</strong> Collectivisation begins; kulaks eliminated</li><li><strong>1928–37:</strong> Five-Year Plans; rapid industrialisation</li><li><strong>1932–33:</strong> Famine (Holodomor) — 7+ million dead</li><li><strong>1936–38:</strong> Great Terror; show trials; purges</li><li><strong>1941–45:</strong> Great Patriotic War; 27 million deaths</li><li><strong>Evaluation:</strong> Industrial superpower at enormous human cost</li></ul>` },

  { id:'h10', title:'Britain, 1918–1951',
    igcse:`<h3>Post-WWI Britain</h3><ul><li><strong>Armistice (Nov 1918):</strong> "Land fit for heroes" — promises unfulfilled</li><li><strong>Economic problems:</strong> Unemployment, debt, declining industries (coal, textiles, shipbuilding)</li><li><strong>General Strike (1926):</strong> Miners' dispute escalated to national strike; 9 days; TUC called it off</li></ul><h3>Interwar Politics</h3><ul><li><strong>Lloyd George Coalition (1918–22):</strong> Post-war reconstruction; Irish independence</li><li><strong>Labour Government (1924, 1929–31):</strong> First Labour administration; MacDonald</li><li><strong>National Government (1931–40):</strong> Coalition led by MacDonald; austerity measures</li></ul><h3>World War II</h3><ul><li><strong>Appeasement:</strong> Chamberlain; Munich Agreement (1938)</li><li><strong>1939:</strong> Britain declares war on Germany</li><li><strong>Churchill becomes PM (May 1940):</strong> "Blood, toil, tears and sweat"</li><li><strong>Battle of Britain (1940):</strong> RAF victory; prevented German invasion</li><li><strong>Atlantic Charter (1941):</strong> Anglo-American war aims</li></ul>`,
    as:`<h3>Social Change</h3><ul><li><strong>Women's suffrage (1918, 1928):</strong> Vote extended to all women over 21</li><li><strong>Housing:</strong> Suburban expansion; "Homes fit for heroes"</li><li><strong>Broadcasting:</strong> BBC founded (1922); radio transformed culture</li></ul><h3>Economic Depression</h3><ul><li><strong>Wall Street Crash impact:</strong> Unemployment reached 3 million (1932)</li><li><strong>Jarrow March (1936):</strong> Unemployed shipyard workers marched to London</li><li><strong>Recovery:</strong> Rearmament boosted economy from 1937</li></ul>`,
    a2:`<h3>Post-War Transformation</h3><ul><li><strong>Labour landslide (1945):</strong> Attlee government; welfare state</li><li><strong>Beveridge Report (1942):</strong> Blueprint for welfare state; "Five Giants" — want, disease, ignorance, squalor, idleness</li><li><strong>NHS (1948):</strong> Free healthcare at point of use</li><li><strong>Nationalisation:</strong> Coal, rail, steel, electricity, gas</li></ul><h3>Decline of Empire</h3><ul><li><strong>Indian independence (1947):</strong> Partition into India and Pakistan</li><li><strong>End of British Raj:</strong> Mountbatten as last Viceroy</li><li><strong>Palestine:</strong> British withdrawal (1948); UN partition plan</li></ul>`,
    summary:`<ul><li><strong>1918:</strong> WWI ends; Lloyd George promises "land fit for heroes"</li><li><strong>1926:</strong> General Strike</li><li><strong>1928:</strong> Equal suffrage for women</li><li><strong>1931–40:</strong> National Government; Depression; appeasement</li><li><strong>1940:</strong> Churchill PM; Battle of Britain</li><li><strong>1945:</strong> Labour landslide; Attlee government</li><li><strong>1948:</strong> NHS established</li></ul>` },

  { id:'h11', title:'The Origins of the Civil War in the USA',
    igcse:`<h3>Slavery & the South</h3><ul><li><strong>Cotton kingdom:</strong> Southern economy dependent on slave labour</li><li><strong>1820:</strong> Missouri Compromise — slavery banned north of 36°30′</li><li><strong>1850:</strong> Compromise of 1850 — California free, Fugitive Slave Law</li><li><strong>1854:</strong> Kansas-Nebraska Act — popular sovereignty; "Bleeding Kansas"</li></ul><h3>Abolitionism</h3><ul><li><strong>Uncle Tom's Cabin (1852):</strong> Stowe's novel galvanised anti-slavery sentiment</li><li><strong>Harriet Tubman:</strong> Underground Railroad; rescued 70+ enslaved people</li><li><strong>John Brown (1859):</strong> Raid on Harper's Ferry; executed as martyr</li></ul><h3>Road to War</h3><ul><li><strong>1860:</strong> Lincoln elected president; South Carolina secedes (Dec 1860)</li><li><strong>Confederate States (1861):</strong> 11 southern states form CSA; Jefferson Davis president</li><li><strong>Fort Sumter (12 April 1861):</strong> Confederate attack starts war</li></ul>`,
    as:`<h3>Political Failure</h3><ul><li><strong>Failure of compromise:</strong> Each compromise postponed but deepened divisions</li><li><strong>Dred Scott (1857):</strong> Supreme Court ruled African Americans could not be citizens; Missouri Compromise unconstitutional</li><li><strong>Lincoln-Douglas debates (1858):</strong> Slavery expansion issue central</li></ul><h3>Economic Differences</h3><ul><li><strong>North:</strong> Industrialising, free labour, tariffs, infrastructure</li><li><strong>South:</strong> Agricultural, slave labour, opposed tariffs, states' rights</li></ul>`,
    a2:`<h3>Was the War Inevitable?</h3><ul><li><strong>Inevitabilist:</strong> Deep economic, social, moral divisions made war unavoidable</li><li><strong>Revisionist:</strong> Political failures of 1850s; compromise was possible</li><li><strong>Contingency:</strong> Specific events (Lincoln's election, secession) triggered war</li></ul>`,
    summary:`<ul><li><strong>1820:</strong> Missouri Compromise</li><li><strong>1850:</strong> Compromise of 1850; Fugitive Slave Law</li><li><strong>1854:</strong> Kansas-Nebraska Act</li><li><strong>1857:</strong> Dred Scott decision</li><li><strong>1860:</strong> Lincoln elected; South Carolina secedes</li><li><strong>1861:</strong> Fort Sumter — war begins</li></ul>` },

  { id:'h12', title:'International Relations, 1871–1945',
    igcse:`<h3>Bismarck's System (1871–90)</h3><ul><li><strong>Three Emperors' League (1873):</strong> Germany, Russia, Austria-Hungary</li><li><strong>Dual Alliance (1879):</strong> Germany-Austria — against Russia</li><li><strong>Triple Alliance (1882):</strong> Added Italy</li><li><strong>Reinsurance Treaty (1887):</strong> Secret Germany-Russia agreement</li></ul><h3>New Imperialism</h3><ul><li><strong>Scramble for Africa (1884–85):</strong> Berlin Conference; Congo Free State</li><li><strong>Boer War (1899–1902):</strong> Britain vs South African republics; concentration camps</li><li><strong>Open Door Policy (1899):</strong> US access to China markets</li></ul><h3>World War I</h3><ul><li><strong>Causes:</strong> Militarism, alliances, imperialism, nationalism</li><li><strong>1914–18:</strong> Trench warfare; Western Front stalemate</li><li><strong>US entry (1917):</strong> Unrestricted submarine warfare; Zimmerman Telegram</li></ul><h3>Interwar Period</h3><ul><li><strong>League of Nations:</strong> US never joined; failed to prevent aggression</li><li><strong>Appeasement:</strong> Munich (1938); failed to stop Hitler</li><li><strong>1939:</strong> WWII begins</li></ul>`,
    as:`<h3>Peace Settlements</h3><ul><li><strong>Treaty of Versailles (1919):</strong> War guilt (Article 231), reparations, territorial losses, disarmament</li><li><strong>Other treaties:</strong> St Germain (Austria), Trianon (Hungary), Neuilly (Bulgaria), Sèvres (Turkey)</li><li><strong>Criticisms:</strong> Too harsh (Keynes) vs justified (Clemenceau)</li></ul>`,
    a2:`<h3>Why Did Peace Fail?</h3><ul><li><strong>Structural flaws:</strong> League without US; no enforcement mechanism</li><li><strong>Economic instability:</strong> Reparations, hyperinflation, Great Depression</li><li><strong>Rise of totalitarianism:</strong> Hitler, Mussolini — exploited Versailles grievances</li></ul>`,
    summary:`<ul><li><strong>1871–90:</strong> Bismarck's alliance system</li><li><strong>1884–85:</strong> Scramble for Africa</li><li><strong>1914–18:</strong> WWI</li><li><strong>1919:</strong> Treaty of Versailles</li><li><strong>1920s:</strong> League of Nations; Locarno era</li><li><strong>1930s:</strong> Depression; rise of dictators; appeasement</li><li><strong>1939:</strong> WWII begins</li></ul>` }
];

// === GEOMETRY TOPICS ===
const geometryTopics = [
  { id:'g1', title:'Euclidean Geometry Fundamentals',
    igcse:`<h3>Basic Definitions</h3><ul><li><strong>Point:</strong> A location in space with no size</li><li><strong>Line:</strong> Infinite set of points extending in both directions</li><li><strong>Plane:</strong> Flat, two-dimensional surface extending infinitely</li><li><strong>Line segment:</strong> Part of a line between two points</li><li><strong>Ray:</strong> Line extending from a point in one direction infinitely</li></ul><h3>Axioms & Postulates</h3><ul><li><strong>Euclid's 5th Postulate (Parallel Postulate):</strong> Given a line and a point not on it, exactly one parallel line can be drawn through the point</li><li><strong>Non-Euclidean geometries:</strong> Spherical (no parallels), Hyperbolic (many parallels)</li></ul><h3>Notation</h3><ul><li>AB̄ denotes line segment from A to B</li><li>∠ABC denotes angle at vertex B</li><li>△ABC denotes triangle with vertices A, B, C</li></ul>`,
    as:`<h3>Proof Techniques</h3><ul><li><strong>Direct proof:</strong> Assume premises, derive conclusion logically</li><li><strong>Proof by contradiction:</strong> Assume opposite, show contradiction</li><li><strong>Proof by contrapositive:</strong> Prove ¬Q → ¬P instead of P → Q</li></ul><h3>Logical Structure</h3><ul><li><strong>Theorem:</strong> Statement proved true</li><li><strong>Corollary:</strong> Result that follows directly from a theorem</li><li><strong>Lemma:</strong> Minor result used to prove a larger theorem</li></ul>`,
    a2:`<h3>Advanced Foundations</h3><ul><li><strong>Vector space approach:</strong> Points as vectors; lines as affine subspaces</li><li><strong>Coordinate-free geometry:</strong> Using inner products and distances</li></ul>`,
    summary:`<ul><li><strong>Point, line, plane:</strong> Fundamental undefined terms</li><li><strong>Euclid's 5th Postulate:</strong> Parallel lines unique</li><li><strong>Proof methods:</strong> Direct, contradiction, contrapositive</li><li><strong>Notation:</strong> AB̄, ∠ABC, △ABC</li></ul>` },

  { id:'g2', title:'Angles, Parallel Lines & Polygons',
    igcse:`<h3>Angle Types</h3><ul><li><strong>Acute:</strong> 0° < θ < 90°</li><li><strong>Right:</strong> θ = 90°</li><li><strong>Obtuse:</strong> 90° < θ < 180°</li><li><strong>Straight:</strong> θ = 180°</li><li><strong>Reflex:</strong> 180° < θ < 360°</li></ul><h3>Angle Relationships</h3><ul><li><strong>Vertically opposite angles:</strong> Equal</li><li><strong>Angles on a straight line:</strong> Sum to 180°</li><li><strong>Angles around a point:</strong> Sum to 360°</li></ul><h3>Parallel Lines</h3><ul><li><strong>Corresponding angles:</strong> Equal</li><li><strong>Alternate angles:</strong> Equal</li><li><strong>Co-interior angles:</strong> Sum to 180°</li></ul><h3>Polygons</h3><ul><li><strong>Sum of interior angles:</strong> (n − 2) × 180°</li><li><strong>Sum of exterior angles:</strong> Always 360°</li><li><strong>Regular polygon interior angle:</strong> (n − 2) × 180° / n</li></ul>`,
    as:`<h3>Polygon Properties</h3><ul><li><strong>Convex vs concave:</strong> All interior angles < 180° vs at least one > 180°</li><li><strong>Number of diagonals:</strong> n(n − 3)/2</li></ul><h3>Worked Example</h3><div class="formula-box">Find the interior angle of a regular decagon.<br>n = 10<br>Interior angle = (10 − 2) × 180° / 10 = 8 × 18° = 144°</div>`,
    a2:`<h3>Tessellations</h3><ul><li><strong>Regular tessellations:</strong> Only triangles, squares, hexagons</li><li><strong>Semi-regular:</strong> Combination of regular polygons</li></ul>`,
    summary:`<ul><li><strong>Angles on line:</strong> 180°</li><li><strong>Angles at point:</strong> 360°</li><li><strong>Parallel lines:</strong> Corresponding =, alternate =, co-interior = 180°</li><li><strong>Interior angle sum:</strong> (n − 2) × 180°</li><li><strong>Exterior angle sum:</strong> 360°</li></ul>` },

  { id:'g3', title:'Congruence & Similarity',
    igcse:`<h3>Congruence</h3><p>Two shapes are congruent if they have exactly the same shape and size.</p><ul><li><strong>SSS:</strong> Three sides equal</li><li><strong>SAS:</strong> Two sides and included angle equal</li><li><strong>ASA:</strong> Two angles and included side equal</li><li><strong>RHS:</strong> Right angle, hypotenuse, one side equal (right triangles only)</li></ul><h3>Similarity</h3><p>Two shapes are similar if they have the same shape but different sizes.</p><ul><li><strong>AA:</strong> Two angles equal</li><li><strong>SAS (similarity):</strong> Two sides in proportion and included angle equal</li><li><strong>SSS (similarity):</strong> All sides in proportion</li></ul><h3>Properties of Similar Triangles</h3><ul><li>Corresponding angles are equal</li><li>Corresponding sides are in proportion</li><li>Ratio of areas = (scale factor)²</li><li>Ratio of volumes = (scale factor)³</li></ul>`,
    as:`<h3>Proofs of Congruence Conditions</h3><ul><li><strong>SSS proof:</strong> Unique triangle determined by three sides</li><li><strong>SAS proof:</strong> Two sides and included angle fix the triangle</li></ul><h3>Applications</h3><ul><li><strong>Shadow problems:</strong> Using similar triangles to find heights</li><li><strong>Map scales:</strong> 1:n ratio</li></ul>`,
    a2:`<h3>Advanced Similarity</h3><ul><li><strong>Self-similarity:</strong> Fractals; Sierpinski triangle</li><li><strong>Spiral similarity:</strong> Combination of rotation and dilation</li></ul>`,
    summary:`<ul><li><strong>Congruence:</strong> SSS, SAS, ASA, RHS</li><li><strong>Similarity:</strong> AA, SAS (ratio), SSS (ratio)</li><li><strong>Area ratio:</strong> k²</li><li><strong>Volume ratio:</strong> k³</li></ul>` },

  { id:'g4', title:'Pythagoras & Trigonometry in 2D/3D',
    igcse:`<h3>Pythagoras' Theorem</h3><div class="formula-box">a² + b² = c²<br>where c is the hypotenuse</div><h3>Trigonometric Ratios</h3><div class="formula-box">sin θ = opposite / hypotenuse<br>cos θ = adjacent / hypotenuse<br>tan θ = opposite / adjacent</div><h3>Special Angles</h3><ul><li>sin 30° = ½, cos 30° = √3/2, tan 30° = 1/√3</li><li>sin 45° = 1/√2, cos 45° = 1/√2, tan 45° = 1</li><li>sin 60° = √3/2, cos 60° = ½, tan 60° = √3</li></ul><h3>3D Applications</h3><ul><li><strong>Space diagonal of cuboid:</strong> d = √(l² + w² + h²)</li><li><strong>Angle between line and plane:</strong> Use right triangle in 3D</li></ul>`,
    as:`<h3>Sine & Cosine Rules</h3><div class="formula-box">Sine rule: a/sin A = b/sin B = c/sin C = 2R<br>Cosine rule: a² = b² + c² − 2bc cos A<br>Area = ½ab sin C</div><h3>Bearings</h3><ul><li>Measured clockwise from North</li><li>Always given as 3 digits (e.g., 065°)</li></ul>`,
    a2:`<h3>3D Trigonometry</h3><ul><li><strong>Angle between two planes:</strong> Use perpendicular lines</li><li><strong>Angle between skew lines:</strong> Translate one line to intersect</li></ul>`,
    summary:`<ul><li><strong>Pythagoras:</strong> a² + b² = c²</li><li><strong>SOH CAH TOA</strong></li><li><strong>Special angles:</strong> 30°, 45°, 60°</li><li><strong>Sine rule:</strong> a/sin A = 2R</li><li><strong>Cosine rule:</strong> a² = b² + c² − 2bc cos A</li><li><strong>Area:</strong> ½ab sin C</li></ul>` },

  { id:'g5', title:'Circles: Theorems & Properties',
    igcse:`<h3>Circle Terminology</h3><ul><li><strong>Radius (r):</strong> Distance from centre to circumference</li><li><strong>Diameter (d):</strong> d = 2r</li><li><strong>Circumference:</strong> C = 2πr = πd</li><li><strong>Area:</strong> A = πr²</li><li><strong>Arc:</strong> Part of circumference</li><li><strong>Chord:</strong> Line joining two points on circumference</li></ul><h3>Key Theorems</h3><ul><li><strong>Angle at centre:</strong> Twice angle at circumference subtended by same arc</li><li><strong>Angle in semicircle:</strong> 90°</li><li><strong>Angles in same segment:</strong> Equal</li><li><strong>Cyclic quadrilateral:</strong> Opposite angles sum to 180°</li></ul>`,
    as:`<h3>More Theorems</h3><ul><li><strong>Tangent-radius:</strong> Tangent perpendicular to radius at point of contact</li><li><strong>Tangent lengths:</strong> From external point, equal lengths</li><li><strong>Alternate segment:</strong> Angle between tangent and chord = angle in alternate segment</li><li><strong>Intersecting chords:</strong> PA × PB = PC × PD</li></ul><h3>Proof of Angle at Centre</h3><p>Draw radii to form isosceles triangles. External angle equals sum of opposite interior angles.</p>`,
    a2:`<h3>Power of a Point</h3><div class="formula-box">For point P outside circle: PT² = PA × PB<br>where PT is tangent length</div><h3>Radical Axis</h3><ul><li>Locus of points with equal power w.r.t. two circles</li></ul>`,
    summary:`<ul><li><strong>C = 2πr, A = πr²</strong></li><li><strong>Angle at centre = 2 × angle at circumference</strong></li><li><strong>Angle in semicircle = 90°</strong></li><li><strong>Cyclic quad:</strong> Opposite angles = 180°</li><li><strong>Tangent ⊥ radius</strong></li><li><strong>Alternate segment theorem</strong></li></ul>` },

  { id:'g6', title:'Loci & Constructions',
    igcse:`<h3>Loci</h3><ul><li><strong>Locus:</strong> Set of points satisfying a condition</li><li><strong>Fixed distance from point:</strong> Circle</li><li><strong>Equidistant from two points:</strong> Perpendicular bisector</li><li><strong>Equidistant from two lines:</strong> Angle bisector</li><li><strong>Fixed distance from line:</strong> Pair of parallel lines</li></ul><h3>Basic Constructions</h3><ul><li><strong>Perpendicular bisector:</strong> Compass arcs from both endpoints</li><li><strong>Angle bisector:</strong> Compass arcs from vertex, then intersecting arcs</li><li><strong>60° angle:</strong> Equilateral triangle construction</li><li><strong>Perpendicular from point to line:</strong> Compass arcs intersecting line</li></ul>`,
    as:`<h3>Compound Loci</h3><ul><li><strong>Region satisfying multiple conditions:</strong> Intersection of loci</li><li><strong>Example:</strong> Points within 3cm of A and within 2cm of line BC</li></ul>`,
    a2:`<h3>Advanced Constructions</h3><ul><li><strong>Regular polygons:</strong> Using central angles</li><li><strong>Golden ratio:</strong> (1 + √5)/2 ≈ 1.618</li></ul>`,
    summary:`<ul><li><strong>Locus from point:</strong> Circle</li><li><strong>Locus from two points:</strong> Perpendicular bisector</li><li><strong>Locus from two lines:</strong> Angle bisector</li><li><strong>Constructions:</strong> Perpendicular bisector, angle bisector, 60° angle</li></ul>` },

  { id:'g7', title:'Vectors in Geometry',
    igcse:`<h3>Vector Basics</h3><ul><li><strong>Notation:</strong> a⃗ or AB⃗</li><li><strong>Magnitude:</strong> |a⃗| = √(x² + y²)</li><li><strong>Direction:</strong> Angle with positive x-axis</li></ul><h3>Vector Operations</h3><div class="formula-box">Addition: a⃗ + b⃗ = (a₁+b₁, a₂+b₂)<br>Scalar multiplication: k a⃗ = (ka₁, ka₂)<br>Negative: −a⃗ = (−a₁, −a₂)</div><h3>Position Vectors</h3><ul><li><strong>Position vector of point P:</strong> OP⃗ from origin O</li><li><strong>Vector AB⃗:</strong> b⃗ − a⃗</li></ul>`,
    as:`<h3>Midpoint & Section Formula</h3><div class="formula-box">Midpoint: (a⃗ + b⃗)/2<br>Section (m:n): (n a⃗ + m b⃗)/(m + n)</div><h3>Collinearity</h3><ul><li>Points A, B, C collinear if AB⃗ = k BC⃗ for some scalar k</li></ul>`,
    a2:`<h3>Vector Geometry Proofs</h3><ul><li><strong>Parallelogram law:</strong> Diagonals bisect each other</li><li><strong>Centroid:</strong> (a⃗ + b⃗ + c⃗)/3</li></ul>`,
    summary:`<ul><li><strong>Magnitude:</strong> |a⃗| = √(x² + y²)</li><li><strong>AB⃗ = b⃗ − a⃗</strong></li><li><strong>Midpoint:</strong> (a⃗ + b⃗)/2</li><li><strong>Section (m:n):</strong> (n a⃗ + m b⃗)/(m+n)</li><li><strong>Collinear:</strong> AB⃗ = k BC⃗</li></ul>` },

  { id:'g8', title:'Transformations & Matrices',
    igcse:`<h3>Types of Transformation</h3><ul><li><strong>Translation:</strong> Slide; vector (a, b)</li><li><strong>Reflection:</strong> Mirror line; x-axis, y-axis, y = x, y = −x</li><li><strong>Rotation:</strong> Centre, angle, direction (clockwise/anticlockwise)</li><li><strong>Enlargement:</strong> Centre, scale factor k</li></ul><h3>Properties</h3><ul><li>Translation, rotation, reflection preserve shape and size (isometries)</li><li>Enlargement preserves shape but changes size</li><li>Area scale factor = k²</li></ul>`,
    as:`<h3>Matrix Representation</h3><div class="formula-box">Reflection in x-axis: [[1,0],[0,-1]]<br>Reflection in y-axis: [[-1,0],[0,1]]<br>Rotation 90° anticlockwise: [[0,-1],[1,0]]<br>Enlargement scale k: [[k,0],[0,k]]</div><h3>Combined Transformations</h3><ul><li>Matrix multiplication: apply rightmost matrix first</li></ul>`,
    a2:`<h3>Inverse Transformations</h3><ul><li>Inverse of matrix M: M⁻¹ where MM⁻¹ = I</li><li>Reflection is self-inverse</li><li>Rotation by θ: inverse is rotation by −θ</li></ul>`,
    summary:`<ul><li><strong>Translation:</strong> Vector (a, b)</li><li><strong>Reflection:</strong> Mirror line</li><li><strong>Rotation:</strong> Centre, angle, direction</li><li><strong>Enlargement:</strong> Centre, scale factor k; area = k²</li><li><strong>Matrix form:</strong> Reflection, rotation, enlargement</li></ul>` },

  { id:'g9', title:'Coordinate Geometry of Circles & Parabolas',
    igcse:`<h3>Circle Equation</h3><div class="formula-box">Centre (a, b), radius r: (x − a)² + (y − b)² = r²</div><h3>General Form</h3><div class="formula-box">x² + y² + 2gx + 2fy + c = 0<br>Centre: (−g, −f)<br>Radius: √(g² + f² − c)</div><h3>Parabola</h3><div class="formula-box">y = ax² + bx + c<br>Vertex: (−b/2a, c − b²/4a)<br>Axis of symmetry: x = −b/2a</div>`,
    as:`<h3>Tangent to Circle</h3><div class="formula-box">Gradient of radius to point (x₁, y₁): m = (y₁ − b)/(x₁ − a)<br>Tangent gradient: −1/m<br>Tangent equation: (x₁ − a)(x − a) + (y₁ − b)(y − b) = r²</div><h3>Intersection of Line and Circle</h3><ul><li>Substitute line equation into circle equation</li><li>Discriminant > 0: two points; = 0: tangent; < 0: no intersection</li></ul>`,
    a2:`<h3>Parametric Equations</h3><div class="formula-box">Circle: x = a + r cos θ, y = b + r sin θ<br>Parabola: x = at², y = 2at</div><h3>Locus Problems</h3><ul><li>Find equation of path traced by moving point</li></ul>`,
    summary:`<ul><li><strong>Circle:</strong> (x−a)² + (y−b)² = r²</li><li><strong>General form centre:</strong> (−g, −f)</li><li><strong>Parabola vertex:</strong> (−b/2a, c − b²/4a)</li><li><strong>Tangent:</strong> Perpendicular to radius</li></ul>` },

  { id:'g10', title:'3D Geometry & Mensuration',
    igcse:`<h3>3D Shapes</h3><ul><li><strong>Cuboid:</strong> Volume = lwh, Surface area = 2(lw + lh + wh)</li><li><strong>Prism:</strong> Volume = cross-sectional area × length</li><li><strong>Cylinder:</strong> Volume = πr²h, Curved surface = 2πrh</li><li><strong>Cone:</strong> Volume = ⅓πr²h, Curved surface = πrl</li><li><strong>Sphere:</strong> Volume = ⁴⁄₃πr³, Surface area = 4πr²</li></ul><h3>Pyramids</h3><ul><li><strong>Volume:</strong> ⅓ × base area × height</li></ul>`,
    as:`<h3>Frustums</h3><div class="formula-box">Volume = ⅓πh(R² + Rr + r²)<br>where R = base radius, r = top radius</div><h3>Similar Solids</h3><ul><li>Linear ratio: k</li><li>Area ratio: k²</li><li>Volume ratio: k³</li></ul>`,
    a2:`<h3>3D Coordinate Geometry</h3><div class="formula-box">Distance between (x₁, y₁, z₁) and (x₂, y₂, z₂):<br>d = √((x₂−x₁)² + (y₂−y₁)² + (z₂−z₁)²)<br>Midpoint: ((x₁+x₂)/2, (y₁+y₂)/2, (z₁+z₂)/2)</div>`,
    summary:`<ul><li><strong>Cuboid:</strong> V = lwh, SA = 2(lw+lh+wh)</li><li><strong>Cylinder:</strong> V = πr²h, CSA = 2πrh</li><li><strong>Cone:</strong> V = ⅓πr²h</li><li><strong>Sphere:</strong> V = ⁴⁄₃πr³, SA = 4πr²</li><li><strong>Similar solids:</strong> V ratio = k³</li></ul>` }
];

// === ICT TOPICS ===
const ictTopics = [
  { id:'i1', title:'Computer Systems & Hardware',
    igcse:`<h3>Hardware Components</h3><ul><li><strong>CPU (Central Processing Unit):</strong> ALU (Arithmetic Logic Unit), CU (Control Unit), Registers</li><li><strong>RAM (Random Access Memory):</strong> Volatile; stores currently running programs and data</li><li><strong>ROM (Read Only Memory):</strong> Non-volatile; stores BIOS/firmware</li><li><strong>Hard Disk/SSD:</strong> Secondary storage; persistent data</li><li><strong>Input devices:</strong> Keyboard, mouse, scanner, microphone, webcam</li><li><strong>Output devices:</strong> Monitor, printer, speakers, projector</li></ul><h3>How the CPU Works</h3><ul><li><strong>Fetch-Decode-Execute cycle:</strong> Instructions fetched from memory, decoded by CU, executed by ALU</li><li><strong>Clock speed:</strong> Measured in GHz; cycles per second</li><li><strong>Cores:</strong> Multiple processing units for parallel tasks</li></ul>`,
    as:`<h3>Storage Technologies</h3><ul><li><strong>Magnetic:</strong> Hard disks — high capacity, mechanical, slower</li><li><strong>Optical:</strong> CD, DVD, Blu-ray — removable, lower capacity</li><li><strong>Solid State:</strong> SSD, flash drives — no moving parts, faster, more expensive</li><li><strong>Cloud storage:</strong> Remote servers accessed via internet</li></ul><h3>Factors Affecting Performance</h3><ul><li>Clock speed, number of cores, cache size, RAM amount, storage type</li></ul>`,
    a2:`<h3>System Architecture</h3><ul><li><strong>von Neumann architecture:</strong> Stored program concept; data and instructions in same memory</li><li><strong>Harvard architecture:</strong> Separate memory for data and instructions</li><li><strong>Cache memory:</strong> L1 (fastest, smallest), L2, L3</li></ul>`,
    summary:`<ul><li><strong>CPU:</strong> ALU + CU + Registers</li><li><strong>RAM:</strong> Volatile; ROM: Non-volatile</li><li><strong>Fetch-Decode-Execute cycle</strong></li><li><strong>Storage:</strong> Magnetic, Optical, Solid State, Cloud</li><li><strong>Performance:</strong> Clock speed, cores, cache, RAM</li></ul>` },

  { id:'i2', title:'Networks, Internet & Security',
    igcse:`<h3>Network Types</h3><ul><li><strong>LAN (Local Area Network):</strong> Limited area; home, school, office</li><li><strong>WAN (Wide Area Network):</strong> Spans large distances; internet is largest WAN</li><li><strong>WLAN:</strong> Wireless LAN using WiFi</li></ul><h3>Network Hardware</h3><ul><li><strong>Router:</strong> Connects networks; directs traffic</li><li><strong>Switch:</strong> Connects devices within LAN</li><li><strong>Hub:</strong> Broadcasts to all devices (less efficient)</li><li><strong>Modem:</strong> Converts digital to analogue signals</li></ul><h3>Internet & WWW</h3><ul><li><strong>Internet:</strong> Global network of networks</li><li><strong>WWW (World Wide Web):</strong> Information system using HTTP</li><li><strong>URL:</strong> Uniform Resource Locator; web address</li><li><strong>IP Address:</strong> Unique identifier for devices</li></ul>`,
    as:`<h3>Network Topologies</h3><ul><li><strong>Bus:</strong> Single cable; cheap but single point of failure</li><li><strong>Star:</strong> Central hub/switch; easy to manage; hub failure critical</li><li><strong>Mesh:</strong> Multiple paths; redundant but expensive</li></ul><h3>Security Threats</h3><ul><li><strong>Malware:</strong> Viruses, worms, trojans, ransomware, spyware</li><li><strong>Phishing:</strong> Fake emails/websites to steal credentials</li><li><strong>DDoS:</strong> Overwhelm server with traffic</li></ul>`,
    a2:`<h3>Security Measures</h3><ul><li><strong>Firewall:</strong> Filters traffic based on rules</li><li><strong>Encryption:</strong> SSL/TLS for websites; AES for data</li><li><strong>Authentication:</strong> Passwords, 2FA, biometrics</li><li><strong>VPN:</strong> Encrypted tunnel for secure remote access</li><li><strong>Penetration testing:</strong> Ethical hacking to find vulnerabilities</li></ul>`,
    summary:`<ul><li><strong>LAN vs WAN:</strong> Local vs Wide area</li><li><strong>Router, Switch, Hub:</strong> Network hardware</li><li><strong>Internet ≠ WWW</strong></li><li><strong>Threats:</strong> Malware, phishing, DDoS</li><li><strong>Protection:</strong> Firewall, encryption, 2FA, VPN</li></ul>` },

  { id:'i3', title:'Data Representation & Binary',
    igcse:`<h3>Number Systems</h3><ul><li><strong>Binary (base 2):</strong> 0 and 1; computers use binary</li><li><strong>Denary (base 10):</strong> 0–9; human-readable</li><li><strong>Hexadecimal (base 16):</strong> 0–9, A–F; compact representation of binary</li></ul><h3>Binary Conversion</h3><div class="formula-box">Binary to denary: 1011 = 1×8 + 0×4 + 1×2 + 1×1 = 11<br>Denary to binary: Repeated division by 2, remainders read upwards</div><h3>Binary Arithmetic</h3><ul><li><strong>Addition:</strong> 0+0=0, 0+1=1, 1+1=10 (carry 1)</li><li><strong>Overflow:</strong> Result exceeds available bits</li></ul><h3>Character Encoding</h3><ul><li><strong>ASCII:</strong> 7 bits; 128 characters</li><li><strong>Unicode:</strong> Variable length; supports all world languages</li></ul>`,
    as:`<h3>Binary Representations</h3><ul><li><strong>Integers:</strong> Signed (two's complement) vs unsigned</li><li><strong>Floating point:</strong> Mantissa and exponent; IEEE 754 standard</li><li><strong>Images:</strong> Bitmap (pixels) vs Vector (mathematical shapes)</li></ul><h3>Two's Complement</h3><div class="formula-box">Positive 5: 00000101<br>Negative 5: invert + 1 → 11111011</div>`,
    a2:`<h3>Data Compression</h3><ul><li><strong>Lossless:</strong> Run-length encoding, Huffman coding — no data lost</li><li><strong>Lossy:</strong> JPEG, MP3 — removes imperceptible data</li></ul><h3>Sound Representation</h3><ul><li><strong>Sampling rate:</strong> Measurements per second (Hz)</li><li><strong>Bit depth:</strong> Bits per sample</li><li><strong>File size:</strong> Sample rate × bit depth × duration × channels</li></ul>`,
    summary:`<ul><li><strong>Binary:</strong> Base 2; computers use binary</li><li><strong>Hex:</strong> Compact binary representation</li><li><strong>ASCII:</strong> 7-bit character encoding</li><li><strong>Two's complement:</strong> Negative number representation</li><li><strong>Compression:</strong> Lossless vs lossy</li></ul>` },

  { id:'i4', title:'Software, OS & Applications',
    igcse:`<h3>System Software</h3><ul><li><strong>Operating System (OS):</strong> Manages hardware and software resources</li><li><strong>Functions:</strong> Memory management, process scheduling, file management, security, user interface</li><li><strong>Examples:</strong> Windows, macOS, Linux, Android, iOS</li></ul><h3>Application Software</h3><ul><li><strong>Word processors:</strong> Microsoft Word, Google Docs</li><li><strong>Spreadsheets:</strong> Excel, Google Sheets</li><li><strong>Databases:</strong> Access, MySQL</li><li><strong>Web browsers:</strong> Chrome, Firefox, Safari</li></ul><h3>Software Types</h3><ul><li><strong>Open source:</strong> Source code available; free to modify (Linux)</li><li><strong>Proprietary:</strong> Closed source; licensed (Windows)</li></ul>`,
    as:`<h3>Utility Software</h3><ul><li><strong>Anti-virus:</strong> Detects and removes malware</li><li><strong>Disk defragmenter:</strong> Optimises file storage</li><li><strong>Backup software:</strong> Copies data for recovery</li><li><strong>Compression tools:</strong> ZIP, RAR</li></ul><h3>OS Concepts</h3><ul><li><strong>Multitasking:</strong> Running multiple programs simultaneously</li><li><strong>Virtual memory:</strong> Using disk space as RAM extension</li></ul>`,
    a2:`<h3>Programming Languages</h3><ul><li><strong>Low-level:</strong> Assembly, machine code — close to hardware</li><li><strong>High-level:</strong> Python, Java, C++ — human-readable</li><li><strong>Compiled:</strong> Translated to machine code before running (C++)</li><li><strong>Interpreted:</strong> Translated line by line (Python)</li></ul>`,
    summary:`<ul><li><strong>OS:</strong> Manages hardware/software</li><li><strong>Applications:</strong> Word, Excel, browsers</li><li><strong>Open source:</strong> Free to modify</li><li><strong>Proprietary:</strong> Licensed, closed source</li><li><strong>Compiled vs Interpreted:</strong> Pre-translated vs line-by-line</li></ul>` },

  { id:'i5', title:'Databases & Data Management',
    igcse:`<h3>Database Concepts</h3><ul><li><strong>Database:</strong> Organised collection of data</li><li><strong>Table:</strong> Collection of related records</li><li><strong>Record/Row:</strong> One set of data</li><li><strong>Field/Column:</strong> One type of data</li><li><strong>Primary key:</strong> Unique identifier for each record</li><li><strong>Foreign key:</strong> Links tables together</li></ul><h3>Data Types</h3><ul><li><strong>Text/String:</strong> Names, addresses</li><li><strong>Number/Integer:</strong> Whole numbers</li><li><strong>Date/Time:</strong> Calendar data</li><li><strong>Boolean:</strong> True/False, Yes/No</li></ul>`,
    as:`<h3>Relational Databases</h3><ul><li><strong>Normalisation:</strong> Organising data to reduce redundancy</li><li><strong>1NF:</strong> Atomic values; no repeating groups</li><li><strong>2NF:</strong> No partial dependencies</li><li><strong>3NF:</strong> No transitive dependencies</li></ul><h3>SQL Basics</h3><div class="formula-box">SELECT name, age FROM students WHERE grade = 'A';<br>INSERT INTO students (name, age) VALUES ('John', 16);<br>UPDATE students SET age = 17 WHERE name = 'John';<br>DELETE FROM students WHERE age < 15;</div>`,
    a2:`<h3>Database Security</h3><ul><li><strong>Access levels:</strong> Read, write, admin permissions</li><li><strong>Encryption:</strong> Protect sensitive data</li><li><strong>Backup:</strong> Regular copies for disaster recovery</li><li><strong>Validation:</strong> Range checks, format checks, presence checks</li></ul>`,
    summary:`<ul><li><strong>Primary key:</strong> Unique identifier</li><li><strong>Foreign key:</strong> Links tables</li><li><strong>Normalisation:</strong> Reduce redundancy (1NF, 2NF, 3NF)</li><li><strong>SQL:</strong> SELECT, INSERT, UPDATE, DELETE</li><li><strong>Validation:</strong> Range, format, presence checks</li></ul>` },

  { id:'i6', title:'Web Design & HTML/CSS',
    igcse:`<h3>HTML Basics</h3><div class="formula-box">&lt;!DOCTYPE html&gt;<br>&lt;html&gt;<br>&lt;head&gt;&lt;title&gt;Page Title&lt;/title&gt;&lt;/head&gt;<br>&lt;body&gt;<br>&lt;h1&gt;Heading&lt;/h1&gt;<br>&lt;p&gt;This is a paragraph.&lt;/p&gt;<br>&lt;a href="url"&gt;Link&lt;/a&gt;<br>&lt;img src="image.jpg" alt="description"&gt;<br>&lt;/body&gt;<br>&lt;/html&gt;</div><h3>Common Tags</h3><ul><li>&lt;h1&gt; to &lt;h6&gt;: Headings</li><li>&lt;p&gt;: Paragraph</li><li>&lt;a&gt;: Anchor/link</li><li>&lt;img&gt;: Image</li><li>&lt;ul&gt;/&lt;ol&gt;: Unordered/ordered lists</li><li>&lt;table&gt;: Table with &lt;tr&gt;, &lt;td&gt;, &lt;th&gt;</li></ul>`,
    as:`<h3>CSS Styling</h3><div class="formula-box">body { font-family: Arial; background: #f0f0f0; }<br>h1 { color: blue; text-align: center; }<br>.class { padding: 10px; }<br>#id { margin: 20px; }</div><h3>CSS Box Model</h3><ul><li><strong>Content → Padding → Border → Margin</strong></li></ul>`,
    a2:`<h3>Responsive Design</h3><ul><li><strong>Media queries:</strong> @media (max-width: 600px) { ... }</li><li><strong>Flexbox:</strong> Flexible layout</li><li><strong>Grid:</strong> Two-dimensional layout</li></ul>`,
    summary:`<ul><li><strong>HTML:</strong> Structure of web pages</li><li><strong>Tags:</strong> h1-h6, p, a, img, ul, table</li><li><strong>CSS:</strong> Styling — colors, fonts, layout</li><li><strong>Box model:</strong> Content, padding, border, margin</li><li><strong>Responsive:</strong> Media queries, flexbox, grid</li></ul>` },

  { id:'i7', title:'Spreadsheets, Word Processing & Presentation',
    igcse:`<h3>Spreadsheet Features</h3><ul><li><strong>Cells:</strong> Identified by column letter and row number (A1, B2)</li><li><strong>Formulas:</strong> Start with = (e.g., =A1+B1)</li><li><strong>Functions:</strong> SUM, AVERAGE, MAX, MIN, COUNT, IF</li><li><strong>Relative reference:</strong> A1 (changes when copied)</li><li><strong>Absolute reference:</strong> $A$1 (stays fixed)</li></ul><h3>Word Processing</h3><ul><li><strong>Formatting:</strong> Font, size, color, alignment, spacing</li><li><strong>Mail merge:</strong> Personalised letters from database</li><li><strong>Tables:</strong> Organise data in rows and columns</li></ul><h3>Presentations</h3><ul><li><strong>Slides:</strong> Individual pages</li><li><strong>Transitions:</strong> Animation between slides</li><li><strong>Animations:</strong> Effects on individual elements</li></ul>`,
    as:`<h3>Advanced Spreadsheet Functions</h3><div class="formula-box">=IF(A1>50, "Pass", "Fail")<br>=VLOOKUP(value, table, column, FALSE)<br>=COUNTIF(range, criteria)</div><h3>Data Analysis</h3><ul><li><strong>Sorting:</strong> Alphabetical, numerical, custom</li><li><strong>Filtering:</strong> Show only matching rows</li><li><strong>Charts:</strong> Bar, line, pie, scatter</li></ul>`,
    a2:`<h3>Macros & Automation</h3><ul><li><strong>Macro:</strong> Recorded sequence of actions</li><li><strong>Visual Basic for Applications (VBA):</strong> Programming language for Office</li></ul>`,
    summary:`<ul><li><strong>Cell reference:</strong> Relative (A1) vs Absolute ($A$1)</li><li><strong>Functions:</strong> SUM, AVERAGE, IF, VLOOKUP</li><li><strong>Word:</strong> Formatting, mail merge, tables</li><li><strong>Presentations:</strong> Slides, transitions, animations</li></ul>` },

  { id:'i8', title:'Programming Concepts & Algorithms',
    igcse:`<h3>Algorithm Basics</h3><ul><li><strong>Algorithm:</strong> Step-by-step solution to a problem</li><li><strong>Pseudocode:</strong> Informal language for describing algorithms</li><li><strong>Flowcharts:</strong> Visual representation using symbols</li></ul><h3>Control Structures</h3><ul><li><strong>Sequence:</strong> Instructions in order</li><li><strong>Selection:</strong> IF...THEN...ELSE, CASE/SWITCH</li><li><strong>Iteration:</strong> FOR, WHILE, REPEAT...UNTIL loops</li></ul><h3>Variables & Data Types</h3><ul><li><strong>Variable:</strong> Named storage location</li><li><strong>Integer:</strong> Whole numbers</li><li><strong>Real/Float:</strong> Decimal numbers</li><li><strong>String:</strong> Text</li><li><strong>Boolean:</strong> True/False</li></ul>`,
    as:`<h3>Data Structures</h3><ul><li><strong>Array:</strong> Collection of same-type elements</li><li><strong>2D Array:</strong> Table of rows and columns</li><li><strong>Record/Struct:</strong> Collection of different-type fields</li></ul><h3>Searching & Sorting</h3><ul><li><strong>Linear search:</strong> Check each element sequentially</li><li><strong>Binary search:</strong> Divide and conquer; requires sorted data</li><li><strong>Bubble sort:</strong> Compare adjacent elements, swap if needed</li></ul>`,
    a2:`<h3>Object-Oriented Programming</h3><ul><li><strong>Class:</strong> Blueprint for objects</li><li><strong>Object:</strong> Instance of a class</li><li><strong>Attributes:</strong> Data/properties</li><li><strong>Methods:</strong> Functions/behaviours</li><li><strong>Inheritance:</strong> Child class inherits from parent</li><li><strong>Encapsulation:</strong> Data hiding</li></ul>`,
    summary:`<ul><li><strong>Algorithm:</strong> Step-by-step solution</li><li><strong>Control structures:</strong> Sequence, Selection, Iteration</li><li><strong>Arrays:</strong> Collection of elements</li><li><strong>Search:</strong> Linear, Binary</li><li><strong>Sort:</strong> Bubble sort</li><li><strong>OOP:</strong> Class, Object, Inheritance, Encapsulation</li></ul>` },

  { id:'i9', title:'Impact of ICT on Society',
    igcse:`<h3>Positive Impacts</h3><ul><li><strong>Communication:</strong> Email, social media, video calls</li><li><strong>Education:</strong> Online learning, digital resources</li><li><strong>Healthcare:</strong> Telemedicine, electronic records</li><li><strong>Commerce:</strong> E-commerce, global markets</li><li><strong>Entertainment:</strong> Streaming, gaming, social media</li></ul><h3>Negative Impacts</h3><ul><li><strong>Job displacement:</strong> Automation replacing workers</li><li><strong>Privacy concerns:</strong> Data collection, surveillance</li><li><strong>Digital divide:</strong> Gap between those with/without access</li><li><strong>Health issues:</strong> Screen time, cyberbullying, addiction</li></ul>`,
    as:`<h3>Ethical Issues</h3><ul><li><strong>Privacy vs security:</strong> Government surveillance debate</li><li><strong>Intellectual property:</strong> Copyright, piracy, plagiarism</li><li><strong>AI bias:</strong> Algorithms reflecting societal prejudices</li></ul><h3>Environmental Impact</h3><ul><li><strong>E-waste:</strong> Discarded electronics</li><li><strong>Energy consumption:</strong> Data centres use significant power</li><li><strong>Positive:</strong> Remote work reduces travel</li></ul>`,
    a2:`<h3>Future of Work</h3><ul><li><strong>Gig economy:</strong> Freelance platforms</li><li><strong>Remote work:</strong> Enabled by ICT</li><li><strong>AI automation:</strong> New jobs created, others lost</li><li><strong>Skills gap:</strong> Need for digital literacy</li></ul>`,
    summary:`<ul><li><strong>Positive:</strong> Communication, education, healthcare, commerce</li><li><strong>Negative:</strong> Job loss, privacy, digital divide, health</li><li><strong>Ethical:</strong> Privacy vs security, copyright, AI bias</li><li><strong>Environment:</strong> E-waste, energy, remote work benefits</li></ul>` },

  { id:'i10', title:'Emerging Technologies & AI',
    igcse:`<h3>Artificial Intelligence</h3><ul><li><strong>Definition:</strong> Machines simulating human intelligence</li><li><strong>Machine Learning:</strong> Systems that learn from data</li><li><strong>Applications:</strong> Voice assistants, recommendation systems, image recognition</li></ul><h3>Internet of Things (IoT)</h3><ul><li><strong>Definition:</strong> Network of connected physical devices</li><li><strong>Examples:</strong> Smart home, wearable fitness trackers, connected cars</li></ul><h3>Cloud Computing</h3><ul><li><strong>IaaS:</strong> Infrastructure as a Service (servers)</li><li><strong>PaaS:</strong> Platform as a Service (development tools)</li><li><strong>SaaS:</strong> Software as a Service (applications)</li></ul>`,
    as:`<h3>Blockchain</h3><ul><li><strong>Distributed ledger:</strong> Decentralised record-keeping</li><li><strong>Cryptocurrency:</strong> Bitcoin, Ethereum</li><li><strong>Applications:</strong> Supply chain, voting, contracts</li></ul><h3>Virtual & Augmented Reality</h3><ul><li><strong>VR:</strong> Immersive simulated environment</li><li><strong>AR:</strong> Digital overlay on real world</li><li><strong>Applications:</strong> Gaming, training, education, medicine</li></ul>`,
    a2:`<h3>Quantum Computing</h3><ul><li><strong>Qubits:</strong> Can be 0 and 1 simultaneously (superposition)</li><li><strong>Potential:</strong> Solve problems impossible for classical computers</li><li><strong>Challenges:</strong> Error correction, stability</li></ul><h3>Ethical AI</h3><ul><li><strong>Transparency:</strong> Explainable AI decisions</li><li><strong>Fairness:</strong> Avoiding bias in training data</li><li><strong>Accountability:</strong> Who is responsible for AI decisions?</li></ul>`,
    summary:`<ul><li><strong>AI:</strong> Machine learning, neural networks</li><li><strong>IoT:</strong> Connected devices</li><li><strong>Cloud:</strong> IaaS, PaaS, SaaS</li><li><strong>Blockchain:</strong> Distributed ledger</li><li><strong>VR/AR:</strong> Immersive technologies</li><li><strong>Quantum:</strong> Qubits, superposition</li><li><strong>Ethics:</strong> Transparency, fairness, accountability</li></ul>` }
];

// Generate all files
let count = 0;

[...historyTopics, ...geometryTopics, ...ictTopics].forEach(topic => {
  const prefix = historyTopics.includes(topic) ? 'history' : geometryTopics.includes(topic) ? 'geometry' : 'ict';
  const code = prefix === 'history' ? '9389 (A-Level) · 0470 (IGCSE)' : prefix === 'geometry' ? '9709 (A-Level) · 0580 (IGCSE)' : '9626 (A-Level) · 0417 (IGCSE)';

  // Detailed notes
  const detailed = template(topic.title, `${prefix}-${topic.id}`, topic.igcse, topic.as, topic.a2, topic.summary);
  fs.writeFileSync(path.join(notesDir, `${prefix}-${topic.id}.html`), detailed);
  count++;

  // Summary notes
  const summary = summaryTemplate(topic.title, `${prefix}-${topic.id}`, topic.summary);
  fs.writeFileSync(path.join(notesDir, `${prefix}-${topic.id}-summary.html`), summary);
  count++;
});

console.log(`Generated ${count} files for History (${historyTopics.length*2}), Geometry (${geometryTopics.length*2}), ICT (${ictTopics.length*2})`);
